def priority(item: float, bins: np.ndarray) -> np.ndarray:
    exact_bonus = 50
    max_count = np.floor(bins / item)
    exact_fill = (max_count * item) == bins
    return np.where(bins >= item, (max_count + exact_bonus * exact_fill) / bins, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    max_count = np.floor(bins / item)
    wasted_space = bins - max_count * item
    return np.where(bins >= item, -wasted_space, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_counts = np.floor(bins / item)
    leftover = bins - fit_counts * item
    scores = fit_counts ** 2 - leftover ** 2
    return np.where(bins >= item, scores, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_counts = np.floor(bins / item)
    leftover = bins - fit_counts * item
    scores = fit_counts / (1 + leftover)
    return np.where(bins >= item, scores, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    remaining = bins - item
    target_remaining = item
    return np.where(remaining >= 0, np.exp(-(remaining - target_remaining) ** 2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    return np.where(item > bins, -np.inf, - (2 * item - bins) ** 2)

